                 F (Z_to_bv 64 0x1e414) fc None m' (seg_rom psegs)
        /\ munch [(RCTX + 920, RCTX + 928)]%Z m m' /\ wmono psegs m m' /\ mem_inv psegs m'
        /\ rw_cells psegs m' (RCTX + 912) [C1 q0; CB 7 q1; C8 (Z_to_bv 64 cur)])
      (MS (mkR x1 sp gp tp t0 t1 t2 (Z_to_bv 64 4096) (Z_to_bv 64 0) (Z_to_bv 64 cur) (Z_to_bv 64 4095) a2 a3 a4 a5 a6 (Z_to_bv 64 214)
               (Z_to_bv 64 RSSP_GUARD) (Z_to_bv 64 RMLOCK) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0x1e3f4) fc None m (seg_rom psegs)).
